INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the main raw material input to the blow room in short-staple (cotton) spinning?', '["Compressed cotton bales","Finished yarn cones","Woven grey fabric","Dyed fiber tops"]'::jsonb, 'Compressed cotton bales', 'The blow room receives compressed raw cotton bales as its input and opens/cleans them into a form suitable for carding — it is the very first stage of the spinning process.', 1, '{"blow-room"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is a ''trash extraction'' system designed to remove from raw cotton during opening and cleaning?', '["Leaf particles, seed-coat fragments, dust, and other non-fiber impurities","Twist from already-spun yarn","Dye color from finished fabric","Moisture from the spinning room air"]'::jsonb, 'Leaf particles, seed-coat fragments, dust, and other non-fiber impurities', 'Trash extraction machinery in the blow room and carding stages removes non-fiber plant matter (leaf, stalk, seed-coat fragments) and dust picked up during cotton harvesting/ginning, before spinning.', 1, '{"trash-extraction"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the function of a ''cone winder'' at the end of spinning?', '["To rewind yarn from ring-frame bobbins onto larger cone packages for storage, transport, or further processing","To insert the initial twist into roving","To open raw cotton fiber bales","To dye yarn before winding"]'::jsonb, 'To rewind yarn from ring-frame bobbins onto larger cone packages for storage, transport, or further processing', 'A cone winder transfers yarn from small ring-spun bobbins onto much larger cone packages, which are easier to handle, transport, and use in downstream weaving/knitting/dyeing operations.', 1, '{"cone-winder"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What does ''splicing'' accomplish during automatic yarn winding?', '["It joins two yarn ends together (after a fault is removed) without a bulky knot, creating a nearly invisible join","It permanently cuts the yarn into short staple lengths","It adds extra twist to weak sections of yarn","It dyes the yarn a matching color at the joint"]'::jsonb, 'It joins two yarn ends together (after a fault is removed) without a bulky knot, creating a nearly invisible join', 'Splicing (often via compressed air) intermingles/twists the fiber ends of two yarn tails together at the join point, creating a strong, low-profile connection — far less bulky and visible than a traditional hand or mechanical knot.', 1, '{"splicing"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why do modern winding machines generally prefer splicing over simple knotting when joining yarn ends?', '["Knots create a bulky, visible thick spot that can cause problems in downstream weaving/knitting (e.g., catching in healds or needles)","Splicing is always weaker than any knot, but used anyway for cost reasons","Knots have no effect on downstream processing quality","Splicing removes twist entirely from the yarn at the join, unlike knots"]'::jsonb, 'Knots create a bulky, visible thick spot that can cause problems in downstream weaving/knitting (e.g., catching in healds or needles)', 'A traditional knot creates a noticeably thicker spot in the yarn that can catch on heald eyes, reed dents, or knitting needles, causing processing problems or visible fabric defects — splices are much slimmer and smoother, minimizing this risk.', 2, '{"splicing-vs-knotting"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is a ''slub'' as a yarn fault (as opposed to an intentional slub-effect yarn)?', '["An unintentional, localized thick place in the yarn caused by processing irregularity","A permanent color variation caused by dyeing","A planned decorative thick-thin texture effect","The standard twist level of a finished yarn"]'::jsonb, 'An unintentional, localized thick place in the yarn caused by processing irregularity', 'As an unintentional fault, a slub is a localized thick place from processing problems (e.g., drafting irregularity, fiber bunching) — distinct from intentionally designed ''slub yarns'' used for decorative textured fabric effects.', 1, '{"slub-fault"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is generally true about the relationship between yarn twist and fabric handle (softness/stiffness), all else equal?', '["Higher twist tends to make yarn (and resulting fabric) feel harder/stiffer, while lower twist tends to feel softer","Twist level has no relationship to fabric handle at all","Lower twist always makes yarn stronger and stiffer than higher twist","Twist only affects yarn color, not handle"]'::jsonb, 'Higher twist tends to make yarn (and resulting fabric) feel harder/stiffer, while lower twist tends to feel softer', 'As twist increases, fibers are bound more tightly and rigidly together, generally producing a harder, crisper yarn and fabric handle; lower-twist yarns allow more fiber mobility, giving a softer, fuller hand — an important design consideration beyond just strength.', 1, '{"twist","fabric-handle"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why might a spinning mill deliberately choose a slightly LOWER twist multiplier for a yarn intended for knitting compared to weaving, given similar count and fiber?', '["Knitted fabrics often benefit from a softer yarn handle and greater loop flexibility, which lower twist helps provide, whereas weaving yarns need more twist-related strength to withstand loom stresses","Lower twist always makes any yarn completely unusable for any purpose","Twist multiplier has no relationship to end-use application at all","Knitting yarns always require higher twist than weaving yarns in every case"]'::jsonb, 'Knitted fabrics often benefit from a softer yarn handle and greater loop flexibility, which lower twist helps provide, whereas weaving yarns need more twist-related strength to withstand loom stresses', 'Knitting needs yarn that can flex and form loops smoothly with a soft hand, favoring somewhat lower twist; weaving yarns (especially warp) undergo more mechanical stress (heald/reed friction, tension) and often need higher twist for adequate strength — so twist multiplier is commonly tailored to end use.', 2, '{"twist-multiplier","end-use"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is the general effect of increasing spinning draft (thinning the strand more) on yarn evenness, assuming the machine is well within its designed capability?', '["A well-controlled, appropriate draft level (within design limits) can maintain good evenness while achieving the desired finer count","Any increase in draft always makes yarn perfectly even with zero possible irregularity","Draft has no measurable relationship to yarn evenness under any condition","Draft can only be applied at the ring frame, nowhere else in spinning"]'::jsonb, 'A well-controlled, appropriate draft level (within design limits) can maintain good evenness while achieving the desired finer count', 'Modern drafting systems are engineered to handle a specific range of draft while maintaining good fiber control and evenness; problems (like drafting waves) tend to arise mainly when draft is pushed beyond the system''s designed/controlled capability, not from draft itself.', 2, '{"draft-and-evenness"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is a ''creel'' in the context of spinning preparatory machines (like the draw frame or simplex)?', '["A frame holding multiple input packages (cans of sliver, or roving bobbins) that feed into the machine","The final output package of finished yarn","The comb-like reed used in weaving","A chemical treatment tank used in dyeing"]'::jsonb, 'A frame holding multiple input packages (cans of sliver, or roving bobbins) that feed into the machine', 'A creel holds and organizes the multiple input packages (sliver cans at the draw frame, roving bobbins at the ring frame) that feed material into a spinning machine, ensuring smooth, organized delivery.', 1, '{"creel"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'In drawing (draw frame), why are typically 6-8 sliver ends fed in together rather than just one or two?', '["Combining more slivers increases the statistical averaging (doubling) effect, further improving evenness beyond what fewer slivers would achieve","Feeding more slivers always makes the resulting sliver thicker with no benefit to evenness","The number of input slivers has no effect on output sliver quality at all","More input slivers are used purely to increase machine speed, unrelated to evenness"]'::jsonb, 'Combining more slivers increases the statistical averaging (doubling) effect, further improving evenness beyond what fewer slivers would achieve', 'Per the doubling law, combining more independent slivers statistically improves the evenness of the resultant sliver (irregularities average out more with a higher number of doublings) — hence draw frames typically combine 6-8 card/drawn slivers per passage for effective blending and evenness improvement.', 2, '{"doubling-law","draw-frame"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why do many spinning mills use TWO passages of drawing (draw frame) rather than just one?', '["A second passage further improves fiber parallelization and evenness beyond what a single passage achieves, especially important for finer/higher-quality yarns","A second passage exists only to slow down production for no quality benefit","Two passages are required by law in every spinning mill worldwide","The second passage exists solely to add twist, which the first passage cannot do"]'::jsonb, 'A second passage further improves fiber parallelization and evenness beyond what a single passage achieves, especially important for finer/higher-quality yarns', 'Each additional drawing passage further parallelizes fibers and evens out remaining irregularities (via the doubling/drafting action); a second passage is common practice, especially for finer or higher-quality yarn requirements, to build on the improvements of the first passage.', 2, '{"drawing-passages"}'::text[]);
